    Given a string s and a natural number n, return a list of words from s that contain exactly n consonants,
    preserving their original order.

    If s is empty, return an empty string.

    The function must not use any loops and must run in O(1) complexity (interpreted here as no explicit loops;
    recursion or built-in functions with implicit iteration are allowed).

    Note: Input string contains only letters, numbers, and spaces. Numbers do not count as consonants.

    Examples:
    select_words("Mary had a little lamb", 4) ==> ['Mary']
    select_words("Mary had a little lamb", 3) ==> ['had', 'lamb']
    select_words("simple white space", 2) ==> []
    select_words("Hello world", 4) ==> ['Hello']
    select_words("Uncle sam", 3) ==> ['sam']
    """
    if not s:
        return ''

    vowels = set("aeiouAEIOU")

    def is_consonant(ch):
        return ch.isalpha() and ch not in vowels

    def consonant_count(word):
        # Count consonants recursively without loops
        if not word:
            return 0
        return (1 if is_consonant(word[0]) else 0) + consonant_count(word[1:])

    words = s.split()

    # Use filter + map style recursion replacement to avoid explicit loops.
    # But since no loops allowed, we'll use recursion for filtering.

    def filter_words(words_list):
        if not words_list:
            return []
        first, *rest = words_list
        if consonant_count(first) == n:
            return [first] + filter_words(rest)
        else:
            return filter_words(rest)

    return filter_words(words)
