    Given an integer num, return the next smallest palindrome strictly greater than num.
    """

    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    def make_palindrome(left, middle, odd_length):
        if odd_length:
            return left + middle + left[::-1]
        else:
            return left + left[::-1]

    s = str(num)
    length = len(s)

    # Special case: if all 9's, next palindrome is 10..01 (e.g. 999 -> 1001)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    odd_length = (length % 2 != 0)

    if odd_length:
        left = s[:length // 2]
        middle = s[length // 2]
        right = s[length // 2 + 1:]
    else:
        left = s[:length // 2]
        middle = ''
        right = s[length // 2:]

    # Form a palindrome from left, middle
    palindrome = make_palindrome(left, middle, odd_length)
    palindrome_num = int(palindrome)

    # If palindrome is strictly greater than num, return it
    if palindrome_num > num:
        return palindrome_num

    # Otherwise, increment the middle part and mirror again
    if odd_length:
        # Increment the middle digit with carry if needed
        left_middle = left + middle
        incremented = str(int(left_middle) + 1)
        # If length changes after increment, e.g. 999 -> 1000
        if len(incremented) > len(left_middle):
            # This means palindrome length increases by 1
            # e.g. 999 -> 1001 handled above, but here for generic case:
            return int('1' + ('0' * (length -1)) + '1')
        left = incremented[:-1]
        middle = incremented[-1]
    else:
        # Even length: increment the left half
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):
            # Length increased, e.g. 99 -> 100, next palindrome is 10101 for length 4
            return int('1' + ('0' * (length -1)) + '1')
        left = incremented

    palindrome = make_palindrome(left, middle, odd_length)
    return int(palindrome)


