def find_solution(a, b, n):
    """
    Finds the first pair of non-negative integers (x, y) such that:
        a*x + b*y = n
    searching x from 0 upwards.

    Returns:
        (x, y) if a solution exists,
        None if no such non-negative integer solution exists.
    """
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        # then b*y = n => y = n/b if integer and non-negative
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        # then a*x = n => x = n/a if integer and non-negative
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    x = 0
    while a * x <= n:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1

    return None
