def remove_column(collection, pos):
    """
    Remove the element at index `pos` from each inner grouping within `collection`
    only if that inner grouping has an element at that position.

    Args:
        collection: A multi-level collection (e.g., list of lists or tuples).
        pos: The index position to remove from each inner grouping.

    Returns:
        A new collection with the same outer type as the input, where each inner
        grouping has the element at position `pos` removed if possible.
    """
    # Determine the type of the outer collection to preserve it in the output
    outer_type = type(collection)

    # Helper function to remove element at pos from inner grouping if possible
    def remove_from_inner(inner):
        inner_type = type(inner)
        if len(inner) > pos:
            # Remove element at position pos
            # For sequences, create a new sequence without the element at pos
            if isinstance(inner, (list, tuple)):
                new_inner = inner[:pos] + inner[pos+1:]
                # Preserve the inner type (list or tuple)
                if inner_type is tuple:
                    return tuple(new_inner)
                else:
                    return list(new_inner)
            else:
                # For other inner types, try to convert to list and back if possible
                try:
                    as_list = list(inner)
                    if len(as_list) > pos:
                        as_list.pop(pos)
                    # Try to return in original type if possible
                    if inner_type is str:
                        return ''.join(as_list)
                    else:
                        return inner_type(as_list)
                except Exception:
                    # If cannot convert, return as is
                    return inner
        else:
            # Position not present, return inner unchanged
            return inner

    # Process each inner grouping
    new_collection = [remove_from_inner(inner) for inner in collection]

    # Return in the same type as the input collection if possible
    if outer_type is tuple:
        return tuple(new_collection)
    else:
        return new_collection


