def dict_depth(d):
    """
    Calculate the depth of a dictionary, counting only nested dictionaries as increasing depth.
    Nested lists and tuples do NOT increase depth regardless of their contents.
    """
    if not isinstance(d, dict):
        return 0

    max_child_depth = 0
    for value in d.values():
        if isinstance(value, dict):
            child_depth = dict_depth(value)
            if child_depth > max_child_depth:
                max_child_depth = child_depth
        # if value is list or tuple, do NOT increase depth regardless of contents

    return 1 + max_child_depth


