    """
    Finds the first pair of non-negative integers (x, y) such that:
        a * x + b * y = n

    The search scans x from 0 upward and returns the first valid (x, y) found.
    If no solution exists with non-negative x and y, returns None.

    Parameters:
        a (int): coefficient of x
        b (int): coefficient of y
        n (int): target value

    Returns:
        tuple: (x, y) if a solution is found, else None
    """
    if b == 0:
        # Avoid division by zero; equation is a*x = n
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    x = 0
    while True:
        remainder = n - a * x
        if remainder < 0:
            # Since increasing x only decreases remainder further,
            # no solutions will be found beyond this point
            break
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1

    return None


