def next_smallest_palindrome(num: int) -> int:
    """
    Given an integer num, find the next smallest palindrome strictly greater than num.
    """
    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    def mirror_left_to_right(s):
        n = len(s)
        half = n // 2
        if n % 2 == 0:
            return s[:half] + s[:half][::-1]
        else:
            return s[:half+1] + s[:half][::-1]

    def increment_middle(s):
        """
        Increment the middle digit(s) of the string s (which represents a number),
        and return the new string after increment and carry.
        """
        s = list(s)
        n = len(s)
        mid = n // 2
        left = mid - 1
        right = mid + 1 if n % 2 else mid

        # Increment the middle digit(s)
        if n % 2 == 1:
            # odd length, increment middle digit
            if s[mid] != '9':
                s[mid] = str(int(s[mid]) + 1)
                return "".join(s)
            else:
                s[mid] = '0'
                carry = 1
        else:
            carry = 1

        # Propagate the carry to the left side and mirror to right
        while left >= 0 and carry > 0:
            new_digit = (int(s[left]) + carry)
            carry = new_digit // 10
            s[left] = str(new_digit % 10)
            s[right] = s[left]
            left -= 1
            right += 1

        # If carry is still left, it means we had all 9's in left half
        if carry > 0:
            # This means the number was like 999...999 and increment made it 1000...0001
            s = ['1'] + ['0'] * (n - 1) + ['1']
            return "".join(s)

        # Copy the left side mirror to right side if not done already
        while left >= 0:
            s[right] = s[left]
            left -= 1
            right += 1

        return "".join(s)

    s = str(num)
    n = len(s)

    # Special case: if all digits are 9, next palindrome is 10...01 with length n+1
    if is_all_nines(s):
        return int('1' + ('0' * (n - 1)) + '1')

    # Start by constructing the palindrome by mirroring left to right
    palindrome = mirror_left_to_right(s)

    # If palindrome is strictly greater than num, return it
    if int(palindrome) > num:
        return int(palindrome)

    # Otherwise, increment the middle part and mirror again
    palindrome = increment_middle(palindrome)
    return int(palindrome)


