    """
    Find the next smallest palindrome strictly greater than the given number.

    Args:
        num (int): The input number.

    Returns:
        int: The next smallest palindrome greater than num.
    """
    def is_all_nines(s: str) -> bool:
        return all(ch == '9' for ch in s)

    s = str(num)
    length = len(s)

    # If all digits are 9, the next palindrome is 10...01 (length+1 digits)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to create a palindrome by mirroring left to right
    def create_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    odd_length = (length % 2 != 0)
    mid = length // 2

    # Split into left, middle, right
    if odd_length:
        left = s[:mid+1]
        right = s[mid+1:]
    else:
        left = s[:mid]
        right = s[mid:]

    # Create palindrome by mirroring left to right
    palindrome = create_palindrome(left, odd_length)

    # If palindrome is greater than num, return it
    if int(palindrome) > num:
        return int(palindrome)

    # Otherwise, need to increment the middle part and mirror again
    if odd_length:
        # Increment the left (which includes the middle digit)
        incremented = str(int(left) + 1)
        # If increment causes length increase (e.g. 999 -> 1000)
        if len(incremented) > len(left):
            # This means the palindrome length increases by 1 digit, handle separately:
            # For example 999 -> next palindrome is 1001
            return int('1' + ('0' * (length - 1)) + '1')
        palindrome = create_palindrome(incremented, odd_length)
    else:
        # Even length: increment left
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):
            # Similar case as above, e.g. 99 -> 101
            return int('1' + ('0' * (length - 1)) + '1')
        palindrome = create_palindrome(incremented, odd_length)

    return int(palindrome)


