def substract_elements(*collections):
    """
    Compute element-wise differences by subtracting corresponding elements across nested collections.

    Args:
        *collections: Two or more nested collections (lists or tuples) of the same structure.

    Returns:
        A nested collection (matching the input structure) of the same shape,
        where each element is the difference obtained by subtracting corresponding elements
        from the second to the last collections from the first collection.

    Raises:
        ValueError: If less than two collections are provided or if the structures don't match.
    """
    if len(collections) < 2:
        raise ValueError("At least two collections are required.")

    def check_structure(a, b):
        if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
            if len(a) != len(b):
                return False
            return all(check_structure(x, y) for x, y in zip(a, b))
        return not (isinstance(a, (list, tuple)) or isinstance(b, (list, tuple)))

    def subtract_recursive(*elems):
        # elems are corresponding elements from each collection at the same position
        first, *rest = elems
        if isinstance(first, (list, tuple)):
            # Preserve the type of the first collection (list or tuple)
            coll_type = type(first)
            return coll_type(subtract_recursive(*items) for items in zip(*elems))
        else:
            # Subtract all subsequent elements from the first element
            result = first
            for val in rest:
                result -= val
            return result

    # Check all structures are the same
    first = collections[0]
    for other in collections[1:]:
        if not check_structure(first, other):
            raise ValueError("All input collections must have the same nested structure.")

    return subtract_recursive(*collections)
