def next_smallest_palindrome(num: int) -> int:
    """
    Find the next smallest palindrome strictly greater than num.
    """

    def is_all_nines(s: str) -> bool:
        return all(ch == '9' for ch in s)

    def next_palindrome_str(s: str) -> str:
        n = len(s)
        if is_all_nines(s):
            # For all 9's, next palindrome is 1 followed by n-1 zeros and 1
            return '1' + ('0' * (n - 1)) + '1'

        half_len = (n + 1) // 2
        # Left half including middle if odd
        left = s[:half_len]
        # Mirror left to right to form palindrome
        if n % 2 == 0:
            pal = left + left[::-1]
        else:
            pal = left + left[:-1][::-1]

        if pal > s:
            # The palindrome formed by mirroring left is already greater
            return pal
        else:
            # Need to increment the left half and mirror again
            # Convert left to int, add 1
            left_num = int(left) + 1
            left_str = str(left_num)
            # If length increased after increment (e.g. 999 + 1 = 1000)
            if len(left_str) > len(left):
                # This means palindrome length increases by 1 (e.g. 999 -> 1001)
                if n % 2 == 0:
                    # Even length case: now length +1, so palindrome is:
                    # left_str + reversed(left_str[:-1])
                    pal = left_str + left_str[:-1][::-1]
                else:
                    # Odd length case: palindrome is left_str + reversed(left_str[:-1])
                    pal = left_str + left_str[:-1][::-1]
            else:
                if n % 2 == 0:
                    pal = left_str + left_str[::-1]
                else:
                    pal = left_str + left_str[:-1][::-1]
            return pal

    s = str(num)
    next_pal = next_palindrome_str(s)
    return int(next_pal)


# Example usage:
if __name__ == "__main__":
    test_numbers = [123, 808, 999, 2133, 1, 9, 11, 12321, 12932]
    for number in test_numbers:
        print(f"Next palindrome after {number} is {next_smallest_palindrome(number)}")
```

