def find_solution(a, b, n):
    """
    Find one pair of integers (x, y) such that a*x + b*y = n.
    Returns a tuple (x, y) if a solution exists, otherwise None.
    """

    def extended_gcd(a, b):
        # Returns a tuple (g, x, y) such that a*x + b*y = g = gcd(a, b)
        if b == 0:
            return (a, 1, 0)
        else:
            g, x1, y1 = extended_gcd(b, a % b)
            x = y1
            y = x1 - (a // b) * y1
            return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)

    # Check if n is divisible by gcd(a, b)
    if n % g != 0:
        return None  # No solution

    # Scale the solution to get one valid solution
    x = x0 * (n // g)
    y = y0 * (n // g)

    return (x, y)


# Example usage:
if __name__ == "__main__":
    a, b, n = 15, 25, 100
    solution = find_solution(a, b, n)
    if solution:
        x, y = solution
        print(f"One solution to {a}*x + {b}*y = {n} is x = {x}, y = {y}")
        # Verify:
        print(f"Verification: {a}*{x} + {b}*{y} = {a*x + b*y}")
    else:
        print(f"No integer solution exists for {a}*x + {b}*y = {n}")
