def lcm(a, b):
    """Return the least common multiple of two positive integers a and b."""
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x
    return a * b // gcd(a, b)

# Example usage:
if __name__ == "__main__":
    print(lcm(12, 18))  # Output: 36
    print(lcm(7, 5))    # Output: 35
